//#region src/cache/app-page-parts.ts
/**
* Whether the response-stage props select an App page's own document or RSC
* payload, the two parts Next.js keeps in one entry, rather than a variant.
*/
function isCanonicalAppPage(responseStageProps, isRscRequest) {
	return responseStageProps !== null && typeof responseStageProps === "object" && Reflect.get(responseStageProps, "kind") === "app-page" && Reflect.get(responseStageProps, "isRscRequest") === isRscRequest && (Reflect.get(responseStageProps, "matchKind") === "request" || Reflect.get(responseStageProps, "matchKind") === "resolved") && (!isRscRequest || Reflect.get(responseStageProps, "renderMode") === "navigation") && Reflect.get(responseStageProps, "interceptionContext") === null && Reflect.get(responseStageProps, "interceptionId") === null && Reflect.get(responseStageProps, "mountedSlotsHeader") === null;
}
//#endregion
export { isCanonicalAppPage };
