import { registerFrameworkTracingIntegration } from "./tracer.js";
import { createWorkersTracingIntegration } from "./workers-tracing.js";
import * as cloudflareWorkers from "cloudflare:workers";
//#region src/server/cloudflare-workers-tracing.ts
const tracing = Reflect.get(cloudflareWorkers, "tracing");
if (tracing) registerFrameworkTracingIntegration(createWorkersTracingIntegration(tracing));
//#endregion
export {};
